==== run.ps1
# Runs one arm of one experiment: each scenario -Runs times, one harness at a time.
#   run.ps1 -Experiment blind-calls -Arm search-first -File C:\...\exp\blind-calls\search-first.json
#   run.ps1 -Experiment blind-calls -Arm control                      (no -File: the control, unchanged)
# Records land in exp\<Experiment>\<Arm>\<scenario>-<n>.json beside a .log. A run whose record exists is skipped,
# so an interrupted arm can be started again. When the arm ends, <Arm>\_status.txt says how.
param(
    [Parameter(Mandatory)][string]$Experiment,
    [Parameter(Mandatory)][string]$Arm,
    [string]$File = '',
    [int]$Runs = 3,
    [string[]]$Scenarios = @('petg-question', 'what-is-this', 'desk-ornament', 'outdoor-fitting'),
    [string]$ScenarioDir = 'C:\src\JusPrin\tests\project_journey\scenarios',
    [double]$BudgetUsd = 0.90
)
$exe = 'C:\src\JusPrin\build\tests\shell\Release\shell_integration_harness_exp.exe'
$root = Join-Path $PSScriptRoot $Experiment
$out = Join-Path $root $Arm
$status = Join-Path $out '_status.txt'
New-Item -ItemType Directory -Force $out | Out-Null
Remove-Item $status -ErrorAction SilentlyContinue
function Finish([string]$message, [int]$code) { Set-Content $status $message; $message; exit $code }
if ($File -and -not (Test-Path $File)) { Finish "STOPPED: no experiment file at $File" 2 }

# List price for deepseek/deepseek-v4-flash on OpenRouter, with no discount for cached input, so this overstates.
function Spent {
    $in = 0; $outTokens = 0
    Get-ChildItem $root -Recurse -Filter *.log -ErrorAction SilentlyContinue | ForEach-Object {
        Select-String -Path $_.FullName -Pattern 'LIVE USAGE .*input_tokens=(\d+) cached_input_tokens=\d+ output_tokens=(\d+)' | ForEach-Object {
            $in += [int64]$_.Matches[0].Groups[1].Value; $outTokens += [int64]$_.Matches[0].Groups[2].Value
        }
    }
    [pscustomobject]@{ Input = $in; Output = $outTokens; Usd = [math]::Round($in * 0.091 / 1e6 + $outTokens * 0.182 / 1e6, 3) }
}

$line = Get-Content "$HOME\.config\jusprin\prompt-test.env" | Where-Object { $_ -match '^(export )?OPENROUTER_API_KEY=' } | Select-Object -First 1
$env:OPENROUTER_API_KEY = ($line -replace '^(export )?OPENROUTER_API_KEY=', '').Trim().Trim('"').Trim("'")
$env:WEBVIEW2_USER_DATA_FOLDER = "C:\Users\guitest\AppData\Local\Temp\claude\jw-$Experiment-$Arm"

foreach ($i in 1..$Runs) {
    foreach ($name in $Scenarios) {
        $record = Join-Path $out "$name-$i.json"; $log = Join-Path $out "$name-$i.log"
        if (Test-Path $record) { "$Arm $name-$i already recorded"; continue }
        $spent = Spent
        if ($spent.Usd -ge $BudgetUsd) { Finish "STOPPED: this experiment has spent about `$$($spent.Usd) of its `$$BudgetUsd ($($spent.Input) input, $($spent.Output) output tokens)" 5 }
        $arguments = @('--journey', (Join-Path $ScenarioDir "$name.json"), $record)
        if ($File) { $arguments += @('--journey-experiment', $File) }
        & $exe @arguments 2> $log
        $code = $LASTEXITCODE
        $summary = (Select-String -Path $log -Pattern 'HARNESS JOURNEY' | Select-Object -Last 1).Line
        $problem = (Select-String -Path $log -Pattern 'HARNESS ERROR' | Select-Object -Last 1).Line
        "$Arm $name-$i exit=$code $summary $problem"
        # A key or quota refusal means stop, not retry.
        if (Select-String -Path $log -Pattern 'status=(401|402|403|429)' -Quiet) { Finish 'STOPPED: the provider refused the key or the quota' 4 }
        # An experiment that could not be applied would fail every run the same way.
        if (Select-String -Path $log -Pattern 'HARNESS ERROR journey experiment' -Quiet) { Finish 'STOPPED: the experiment file does not apply' 6 }
    }
}
$spent = Spent
Finish "$Arm done. Experiment total so far: about `$$($spent.Usd) ($($spent.Input) input, $($spent.Output) output tokens)" 0
==== wait.ps1
# Blocks until an arm started with run.ps1 has ended, or about nine minutes have passed.
#   wait.ps1 -Experiment blind-calls -Arm search-first
# Call it again while it reports "still running".
param([Parameter(Mandatory)][string]$Experiment, [Parameter(Mandatory)][string]$Arm, [int]$Seconds = 540)
$out = Join-Path (Join-Path $PSScriptRoot $Experiment) $Arm
$status = Join-Path $out '_status.txt'
$until = (Get-Date).AddSeconds($Seconds)
while ((Get-Date) -lt $until -and -not (Test-Path $status)) { Start-Sleep -Seconds 15 }
$records = @(Get-ChildItem $out -Filter *.json -ErrorAction SilentlyContinue).Count
if (Test-Path $status) { "ended with $records records: $(Get-Content $status)" } else { "still running: $records records so far" }
